mapper.select:
SELECT , COALESCE(pc.cnt, 0) AS periodPostCount FROM series s LEFT JOIN (SELECT series_id, COUNT(*) AS cnt FROM community_post WHERE deleted_at IS NULL AND created_at >= #{periodStart} GROUP BY series_id) pc ON pc.series_id = s.series_id WHERE 1 = 1
AND ( COALESCE(pc.cnt, 0) < #{lastValue} OR (COALESCE(pc.cnt, 0) = #{lastValue} AND s.series_id < #{lastId}) )
ORDER BY periodPostCount DESC, s.series_id DESC LIMIT #{size}

SELECT , lp.lastPostedAt AS lastPostedAt FROM series s LEFT JOIN (SELECT series_id, MAX(created_at) AS lastPostedAt FROM community_post WHERE deleted_at IS NULL GROUP BY series_id) lp ON lp.series_id = s.series_id WHERE 1 = 1
AND ( lp.lastPostedAt < #{lastValue} OR (lp.lastPostedAt = #{lastValue} AND s.series_id < #{lastId}) OR lp.lastPostedAt IS NULL )
AND lp.lastPostedAt IS NULL AND s.series_id < #{lastId}
ORDER BY (lp.lastPostedAt IS NULL) ASC, lp.lastPostedAt DESC, s.series_id DESC LIMIT #{size}

SELECT sa.series_id AS seriesId, g.genre_id AS id, g.genre_kor AS name FROM series_anime sa JOIN animegenres ag ON ag.anime_id = sa.anime_id JOIN genres g ON g.genre_id = ag.genre_id WHERE sa.series_id IN
#{seriesId}
AND sa.anime_id = (SELECT sa2.anime_id FROM series_anime sa2 WHERE sa2.series_id = sa.series_id ORDER BY sa2.sort_order ASC, sa2.anime_id ASC LIMIT 1) ORDER BY sa.series_id ASC, g.genre_id ASC
